    assert result["stats"]["atlas_sprite_count"] == 3
    assert result["stats"]["target_sprite_count"] == 2
    assert result["stats"]["visual_sprite_asset_count"] == 3
    assert result["stats"]["exported_sprite_image_count"] == 3
