        "_MessagePool.Inst_get():F_Register(_SM_DigitDoorActivityEnd:getId(),typeof(_SM_DigitDoorActivityEnd),function(msg)\n"
        "self.SM_DigitDoorActivityEndFun(msg)\nend)\n"
