def test_fanxiu_doupotd_pvp_report_pcap_observed_schema_coverage_probe_maps_fields(tmp_path, monkeypatch):
    export_root = tmp_path / "exports"
    output_dir = export_root / "parsed_configs" / "doupotd_catalog"
