                "RedDotMgr.Inst_get():RaiseRedDotEvent(RedDotID.BLLD_SkipLevel,true)",
                "RedDotMgr.Inst_get():RaiseRedDotEvent(RedDotID.BLLD_FaQiUpgrade,true)",
                "end",
