                "end",
                "function _M.GetActivityVoByBaseId(self,baseId)",
                "return self._ActivityBaseDic:LuaDic_GetItem(baseId)",
                "end",
                "function _M.GetActivityVo(self,activityId)",
                "return self._ActivityInfo:LuaDic_GetItem(activityId)",
