                "_MessagePool.Inst_get():F_Register(_CM_SyncYunmengPkInfo:getId(),typeof(_CM_SyncYunmengPkInfo))",
                "_MessagePool.Inst_get():F_Register(_SM_SyncYunmengPkInfo:getId(),typeof(_SM_SyncYunmengPkInfo),function(msg)",
