def test_fanxiu_doupotd_pcap_observed_quanf_draw_syn_chain_probe_maps_round_info_cache(tmp_path):
    export_root = tmp_path / "exports"
    output_dir = export_root / "parsed_configs" / "doupotd_catalog"
