        "self.baseId=0\n"
        "self.id=0\n"
        "self.num=0\n"
        "end\n"
        "function _M.reading(self)\n"
        "self.baseId=self:readInt()\n"
        "self.id=self:readLong()\n"
        "self.num=self:readInt()\n"
