        "local increaseDamage=model:GetIncreaseDamage()\n"
        "local finalDamage=finalAttack*(1+increaseDamage/10000)\n"
        "local criAddDamage=model:GetCriAddDamage()\n"
        "BLLDHurtDataExecute(finalDamage)\n"
